def marker_color(risk):
    risk = str(risk).upper()
    if risk == "SAFE": return [38, 166, 91, 220]
    if risk == "CAUTION": return [35, 112, 190, 230]
    if risk == "HIGH": return [224, 74, 60, 235]
    if risk == "CRITICAL": return [155, 25, 25, 245]
    return [100, 120, 110, 220]

# -------------------- Automatic Android-style alert --------------------
def trigger_mobile_alert(risk, name, thi):
    if "last_alert_risk" not in st.session_state:
        st.session_state.last_alert_risk = "SAFE"

    previous = st.session_state.last_alert_risk
    if risk in ["HIGH", "CRITICAL"] and previous not in ["HIGH", "CRITICAL"]:
        title = "🚨 High Heat-Stress Detected" if language == "English" else "🚨 ಹೆಚ್ಚಿನ ಶಾಖ-ಒತ್ತಡ ಪತ್ತೆಯಾಗಿದೆ"
        body = (
            f"{name} needs immediate attention. THI {thi:.1f}."
            if language == "English"
            else f"{name} ಗೆ ತಕ್ಷಣ ಗಮನ ಅಗತ್ಯ. THI {thi:.1f}."
        )
        st.toast(f"{title}\n{body}", icon="🚨")

    st.session_state.last_alert_risk = risk

